// The studio wall behind the wheel, far and out of focus: warm plaster in
// the dark, and the window's light falling on it as a soft, skewed patch
// with the faint shadow of its mullions, behind the pot. It falls off to
// near black toward the frame's edges.
//   u0 brightness   u1 drift (px)   u2, u3 patch centre (px)
//   u4, u5 patch half width, half height (px)
float sq(float x) { return x * x; }

float4 shade(float2 pos, float px) {
  float2 sz = size();
  float k = param(0);
  float2 c = float2(param(2) + param(1), param(3));
  float2 half_ = float2(param(4), param(5));
  // the patch leans: the light comes in from the left, a little from above
  float2 q = pos - c;
  q.x -= q.y * 0.16;
  float2 d2 = abs(q) - half_;
  float box = length(max(d2, 0.0)) + min(max(d2.x, d2.y), 0.0);
  float soft = 0.11 * sz.y;
  float patch_ = 1.0 - smoothstep(-soft, soft, box);
  // mullions: one upright, one transom, soft as the patch is
  float bars = exp(-sq((q.x + half_.x * 0.06) / (0.035 * sz.y))) * 0.30
             + exp(-sq((q.y + half_.y * 0.22) / (0.030 * sz.y))) * 0.24;
  patch_ *= 1.0 - bars * smoothstep(0.0, 0.6, patch_);
  // brighter toward the window side of the patch
  patch_ *= 0.86 + 0.14 * smoothstep(half_.x, -half_.x, q.x);
  // the spill around it, and the room's dark
  float2 g = (pos - c) / sz.y;
  float spill = exp(-dot(g * float2(1.2, 1.0), g * float2(1.2, 1.0)) * 3.2);
  float n = snoise(float3(pos / sz.y * 2.4, 3.7)) * 0.5 + snoise(float3(pos / sz.y * 6.0, 9.1)) * 0.25;
  float3 deep = float3(0.0040, 0.0029, 0.0023);
  float3 mid = float3(0.030, 0.021, 0.015);
  float3 lit = float3(0.235, 0.170, 0.122);
  float3 col = deep + mid * spill * k + lit * patch_ * k;
  col *= 1.0 + 0.05 * n;
  // the very top and bottom of the frame fall into shadow
  float y = pos.y / sz.y;
  col *= lerp(0.5, 1.0, smoothstep(0.0, 0.42, y)) * lerp(1.0, 0.6, smoothstep(0.75, 1.0, y));
  return float4(col, 1.0);
}

// Clay thrown on a wheel, lit by one large window on the left in a warm,
// dark room. The vessel is a lathe distance field whose profile is keyed:
//   u0 height   u1 radius   u2 open   u3 dome   u4 belly   u5 neck   u6 lip
//   u7 touch (0..1 up the wall: where the hands were last, wettest there)
//   u8 centred (0: an off-centre lump that wobbles as it turns, 1: true)
// The camera orbits the wheel as the raymarch op's does:
//   u9 azimuth  u10 elevation  u11 distance  u12 target height
//   u13 window azimuth (degrees: it sweeps at the end)  u14 lens shift (frame heights,
//   + moves the image down)  u15 aperture. Field of view: FOV.
// Each pixel takes NS samples, each at its own sub-pixel spot, lens point and
// moment of the shutter: antialiasing, depth of field and the wheel's motion
// blur in one pass. Misses are transparent: the backdrop is its own layer.

#define NS 6
static const float RPS = 0.72;              // wheel turns per second
static const float T_SLOW = 6.9;            // the potter lifts off the pedal
static const float T_STOP = 9.2;            // the wheel is still
static const float SHUTTER = 0.5 / 30.0;    // seconds the shutter is open
static const float EXPOSURE = 1.0;
static const float FOV = 22.0;               // vertical, degrees
static float g_spin = 0.0;                  // wheel angle of this sample
static float g_dspin = 0.0;                 // angle it turns within the sample
static float g_rnd = 0.0;                   // per-sample random
static float g_ring = 1.0;                  // < 1: rings filled (the water film's surface)

// ---- helpers -------------------------------------------------------------
float sq(float x) { return x * x; }
float smax(float a, float b, float k) { float h = saturate(0.5 - 0.5 * (b - a) / k); return lerp(b, a, h) + k * h * (1.0 - h); }
float smin(float a, float b, float k) { float h = saturate(0.5 + 0.5 * (b - a) / k); return lerp(b, a, h) - k * h * (1.0 - h); }
float3 rotY(float3 p, float a) { float c = cos(a), s = sin(a); return float3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z); }
float wrapPi(float a) { return a - 6.2831853 * floor(a / 6.2831853 + 0.5); }
float sdBox2(float2 p, float2 b, float r) { float2 q = abs(p) - b + r; return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r; }
float3 lin(float3 s) { return pow(s, float3(2.2, 2.2, 2.2)); }
float hash21(float2 p) { float3 p3 = frac(float3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return frac((p3.x + p3.y) * p3.z); }

// Wheel angle at time t: steady, then slowing to rest (speed falls as
// (1 - x)^2), in closed form so any frame renders on its own.
float spinAt(float t) {
  float w0 = 6.2831853 * RPS;
  if (t < T_SLOW) return w0 * t;
  float D = T_STOP - T_SLOW;
  float y = 1.0 - saturate((t - T_SLOW) / D);
  return w0 * (T_SLOW + D * (1.0 - y * y * y) / 3.0);
}
float spinRate(float t) {
  return 6.2831853 * RPS * sq(1.0 - saturate((t - T_SLOW) / (T_STOP - T_SLOW)));
}

// ---- the form ------------------------------------------------------------
float kH() { return param(0); }
float kR() { return param(1); }
float kOpen() { return param(2); }
float kDome() { return param(3); }
float kBelly() { return param(4); }
float kNeck() { return param(5); }
float kLip() { return param(6); }
float kTouch() { return param(7); }
float kWob() { return 1.0 - param(8); }
// How far the walls have been pulled: rings, thin walls, a tucked foot.
float pull() { return smoothstep(0.8, 2.0, kH()); }

// The smooth body: radius at normalized height v (0 foot .. 1 rim).
float bodyR(float v) {
  float R = kR();
  float r = R * (1.0 - 0.07 * v);
  r -= 0.07 * R * pull() * (1.0 - smoothstep(0.0, 0.14, v));
  r += kBelly() * exp(-sq((v - 0.40) / 0.25));
  r -= kNeck() * smoothstep(0.58, 0.88, v);
  r += kLip() * sq(smoothstep(0.85, 1.0, v));
  return r;
}
float wallW(float v) { return lerp(0.15, 0.072, v) * lerp(2.3, 1.0, pull()); }
// The rim is a little out of level, as thrown rims are; the lump, lumpy.
float rimH(float th) {
  return kH() + (0.012 * sin(th + 0.9) + 0.004 * sin(3.0 * th - 0.4)) * pull();
}
float lumps(float v, float th) {
  return kWob() * (0.045 * sin(2.0 * th + 0.5 + v) + 0.025 * sin(3.0 * th + 2.0 - 2.0 * v)) * smoothstep(0.0, 0.3, v);
}
// Throwing rings: a spiral ridge climbing about a ring per turn, unevenly
// spaced, pressed unevenly round the turn; soft on the belly, crisper near
// the rim. Returns the offset and its slope per unit v.
float rings(float v, float th, out float dv) {
  float N = 13.0;
  float ph = 6.2831853 * (v * N + 0.32 * sin(v * 6.3 + 1.3) + 0.12 * sin(v * 17.0)) - th;
  float dph = 6.2831853 * (N + 0.32 * 6.3 * cos(v * 6.3 + 1.3) + 0.12 * 17.0 * cos(v * 17.0));
  float env_ = lerp(0.55, 1.25, smoothstep(0.55, 0.92, v)) * (1.0 - 0.6 * smoothstep(0.93, 0.99, v));
  float a = 0.0034 * g_ring * pull() * smoothstep(0.03, 0.12, v) * env_;
  a *= 0.7 + 0.3 * sin(2.0 * th + v * 5.0);
  float sharp = smoothstep(0.6, 0.95, v);
  float s = sin(ph) + (0.18 + 0.22 * sharp) * sin(2.0 * ph + 1.1) + 0.12 * sharp * sin(3.0 * ph + 0.4);
  dv = a * dph * (cos(ph) + 2.0 * (0.18 + 0.22 * sharp) * cos(2.0 * ph + 1.1) + 0.36 * sharp * cos(3.0 * ph + 0.4));
  return a * s;
}
// A finger dragged up the lower wall on the last pull, slanting.
float drag(float v, float th) {
  float c = wrapPi(th - (1.9 + 0.7 * v));
  return exp(-sq(c / 0.11)) * smoothstep(0.08, 0.18, v) * smoothstep(0.55, 0.38, v) * pull();
}
// The off-centre lump, in the wheel's turning frame.
float2 offC() { return float2(0.07, 0.03) * kWob(); }

float clayD(float3 q) {
  q.xz -= offC();
  float r = length(q.xz);
  float th = atan2(q.z, q.x);
  float H = rimH(th) + 0.05 * kWob() * sin(th + 2.2) * smoothstep(0.0, 0.45, r);
  float vc = saturate(q.y / H);
  float e = 0.012;
  float va = min(vc + e, 1.0), vb = max(vc - e, 0.0);
  float r0 = bodyR(vc);
  float dr = (bodyR(va) - bodyR(vb)) / ((va - vb) * H);
  float rdv;
  float ro = r0 + lumps(vc, th) + rings(vc, th, rdv) - 0.009 * g_ring * drag(vc, th);
  float dro = dr + rdv / H;
  float side = (r - ro) / sqrt(1.0 + dro * dro);
  float R = kR(), dome = kDome();
  float top = (q.y - (H - dome * sq(r / R))) / sqrt(1.0 + sq(2.0 * dome * r / (R * R)));
  float d = smax(side, top, 0.05 + 0.3 * dome);
  d = max(d, -q.y - 0.05);
  float op = kOpen();
  if (op > 0.001) {
    float wr = smoothstep(0.0, 0.75, op);
    float w = wallW(vc);
    float idv;
    float ri = (r0 - w + rings(vc, th + 2.1, idv) * 0.8) * wr;
    float dw = (wallW(va) - wallW(vb)) / ((va - vb) * H);
    float dri = (dr - dw + 0.8 * idv / H) * wr;
    float floorY = lerp(H + 0.25, 0.13, smoothstep(0.0, 0.4, op));
    float cav = smax((r - ri) / sqrt(1.0 + dri * dri), floorY - q.y, 0.03 + 0.11 * wr);
    d = smax(d, -cav, 0.022);
  }
  return d;
}

// Cast aluminium wheel head (32 cm), top face at y = 0, and the splash pan round it.
float wheelD(float3 p) {
  float2 d = float2(length(p.xz) - 1.62 + 0.025, abs(p.y + 0.08) - 0.08 + 0.025);
  return min(max(d.x, d.y), 0.0) + length(max(d, 0.0)) - 0.025;
}
float panD(float3 p) {
  // the splash pan sits below the head: its rolled rim just under the top
  float r = length(p.xz);
  float wall = sdBox2(float2(r - 1.92 - 0.06 * saturate(p.y + 0.7), p.y + 0.42), float2(0.03, 0.30), 0.02);
  float rim = length(float2(r - 1.98, p.y + 0.12)) - 0.045;
  float floor_ = sdBox2(float2(r - 1.1, p.y + 0.72), float2(1.2, 0.03), 0.01);
  return min(min(wall, rim), floor_);
}

float2 map(float3 p) {
  float2 res = float2(panD(p), 3.0);
  float dw = wheelD(p);
  float rb = length(p.xz) - (kR() + kBelly() + kLip() + 0.32);
  float bound = max(rb, max(p.y - (kH() + 0.32), -p.y - 0.1));
  // far from the pot, the distance to its bounding cylinder will do; near
  // it (0.5), the real distance: soft shadows read the size of near misses
  float dc = bound > 0.5 ? bound : clayD(rotY(p, -g_spin));
  float d = smin(dc, dw, 0.03);
  float id = dc < dw + 0.004 ? 1.0 : 2.0;
  if (d < res.x) res = float2(d, id);
  return res;
}

// ---- light ---------------------------------------------------------------
// One tall window to the left of camera, a little in front, at pot height.
static const float2 LHALF = float2(2.3, 3.9);
// The window's centre: 8.7 away at azimuth u13 (degrees; it can sweep).
float3 lightC() { float a = radians(param(13)); return float3(8.71 * sin(a), 2.3, 8.71 * cos(a)); }
static const float3 LRAD = float3(1.0, 0.93, 0.84) * 9.5;
float3 lightN() { float3 c = lightC(); return normalize(float3(-c.x, 0.0, -c.z)); }
void lightAxes(out float3 ax, out float3 ay) {
  float3 n = lightN();
  ax = normalize(cross(n, float3(0.0, 1.0, 0.0)));
  ay = cross(ax, n);
}
float edgeFF(float3 a, float3 b, float3 n) {
  float c = clamp(dot(a, b), -0.9999, 0.9999);
  float3 cr = cross(a, b);
  return acos(c) * dot(cr, n) / max(length(cr), 1e-6);
}
// Share of the hemisphere the window fills, cosine weighted (Lambert).
float windowFF(float3 p, float3 n) {
  float3 ax, ay; lightAxes(ax, ay);
  float3 c0 = lightC() - ax * LHALF.x - ay * LHALF.y, c1 = lightC() + ax * LHALF.x - ay * LHALF.y;
  float3 c2 = lightC() + ax * LHALF.x + ay * LHALF.y, c3 = lightC() - ax * LHALF.x + ay * LHALF.y;
  float3 v0 = normalize(c0 - p), v1 = normalize(c1 - p), v2 = normalize(c2 - p), v3 = normalize(c3 - p);
  float s = edgeFF(v0, v1, n) + edgeFF(v1, v2, n) + edgeFF(v2, v3, n) + edgeFF(v3, v0, n);
  return max(s, 0.0) / 6.2831853;
}
// Box-filtered coverage of [-a, a] by a window of half width b around x.
float cover1(float x, float a, float b) { return saturate((min(x + b, a) - max(x - b, -a)) / (2.0 * b)); }
// The window seen in a reflection, blurred by roughness; its mullions show
// only in the sharpest reflections.
float windowSpec(float3 p, float3 r, float rough) {
  float3 n = lightN();
  float dn = dot(r, n);
  if (dn > -1e-3) return 0.0;
  float t = dot(lightC() - p, n) / dn;
  if (t <= 0.0) return 0.0;
  float3 ax, ay; lightAxes(ax, ay);
  float3 h = p + r * t - lightC();
  float u = dot(h, ax), w = dot(h, ay);
  float b = 2.2 * rough * rough * t + 0.015 * t;
  float cx = cover1(u, LHALF.x, b), cy = cover1(w, LHALF.y, b);
  float mx = cover1(u, 0.07, b), my = cover1(w - 0.6, 0.07, b);
  float c = cx * cy - mx * cy - my * cx + mx * my;
  // the sky in the upper panes is brighter than the street below
  float sky = cover1(w - LHALF.y * 0.45, LHALF.y * 0.55, b) * cx;
  return max(c, 0.0) * (0.7 + 0.2 * saturate(1.0 - sq(w / LHALF.y))) + 1.3 * sky * (1.0 - mx);
}
// The room as reflections and ambient light see it: warm and dark, the
// window's light pooled on the wall behind the pot (the backdrop shows the
// same pool), a faint warm bounce on the right, the lit wheel below.
float3 env(float3 d) {
  float3 c = float3(0.011, 0.008, 0.006);
  // the lit patch on the far wall, where the camera's rays past the pot land
  float2 w = float2(d.x - 0.06, d.y + 0.17);
  float pool = smoothstep(0.2, -0.5, d.z) * exp(-dot(w * float2(1.9, 3.2), w * float2(1.9, 3.2)));
  c += float3(0.30, 0.235, 0.18) * pool;
  c += float3(0.026, 0.018, 0.013) * smoothstep(0.3, -0.8, d.x) * smoothstep(-0.4, 0.2, d.y);
  c += float3(0.012, 0.009, 0.007) * smoothstep(0.2, 0.9, d.x);
  c *= lerp(1.0, 0.45, smoothstep(0.05, 0.8, d.y));
  return c;
}

// ---- tracing -------------------------------------------------------------
float2 march(float3 ro, float3 rd) {
  // the scene lives inside r < 2.5, -0.75 < y < 3: clip the ray to it
  float t0 = 0.0, t1 = 60.0;
  float a = dot(rd.xz, rd.xz), b = dot(ro.xz, rd.xz), c = dot(ro.xz, ro.xz) - 2.5 * 2.5;
  float disc = b * b - a * c;
  if (disc < 0.0) return float2(-1.0, -1.0);
  float sd = sqrt(disc);
  t0 = max(t0, (-b - sd) / a); t1 = min(t1, (-b + sd) / a);
  float ya = (-0.75 - ro.y) / rd.y, yb = (3.0 - ro.y) / rd.y;
  t0 = max(t0, min(ya, yb)); t1 = min(t1, max(ya, yb));
  if (t0 > t1) return float2(-1.0, -1.0);
  float t = t0;
  for (int i = 0; i < 160; i++) {
    float2 h = map(ro + rd * t);
    if (h.x < 0.00018 * t) return float2(t, h.y);
    t += h.x * 0.85;
    if (t > t1) break;
  }
  return float2(-1.0, -1.0);
}
float3 calcNormal(float3 p, float t) {
  float e = 0.0005 + 0.00008 * t;
  float2 k = float2(1.0, -1.0);
  return normalize(k.xyy * map(p + k.xyy * e).x + k.yyx * map(p + k.yyx * e).x +
                   k.yxy * map(p + k.yxy * e).x + k.xxx * map(p + k.xxx * e).x);
}
// Occlusion of the window by other geometry (the window's own horizon is in
// windowFF): starts clear of the surface, jittered so steps don't band. The
// plain penumbra estimate: the lathe's distances are bounds, not exact, and
// the triangulated estimate collapses where they overshoot.
float softShadow(float3 ro, float3 rd, float tmax, float k) {
  float res = 1.0, t = 0.12 + 0.05 * g_rnd;
  for (int i = 0; i < 44; i++) {
    float h = map(ro + rd * t).x;
    res = min(res, k * h / t);
    t += clamp(h, 0.015, 0.3);
    if (res < 0.002 || t > tmax) break;
  }
  res = saturate(res);
  return res * res * (3.0 - 2.0 * res);
}
float calcAO(float3 p, float3 n) {
  float occ = 0.0, sca = 1.0;
  for (int i = 0; i < 5; i++) {
    float h = 0.012 + 0.06 * float(i);
    occ += (h - map(p + n * h).x) * sca;
    sca *= 0.78;
  }
  return saturate(1.0 - 2.2 * occ);
}

// ---- materials -----------------------------------------------------------
struct Mat { float3 alb; float metal; float rough; float coat; float coatRough; };

Mat clayMat(float3 p) {
  Mat m;
  float3 q = rotY(p, -g_spin);
  q.xz -= offC();
  float th = atan2(q.z, q.x);
  float H = kH();
  float v = q.y / H;
  float vs = saturate(v);
  float r = length(q.xz);
  float inside = smoothstep(-0.01, -0.03, r - (bodyR(vs) - wallW(vs) * 0.5)) * step(0.02, kOpen());
  float3 base = lin(float3(0.68, 0.37, 0.25));
  float3 slipC = lin(float3(0.78, 0.50, 0.37));
  float3 darkC = lin(float3(0.16, 0.095, 0.07));
  float3 grogC = lin(float3(0.86, 0.71, 0.56));
  float3 alb = float3(0.0, 0.0, 0.0);
  float streakA = 0.0, speck = 0.0, dragA = 0.0, wipeA = 0.0;
  // The texture is averaged over the slice of a turn this sample sees.
  for (int k = 0; k < 3; k++) {
    float a = th + g_dspin * ((float(k) + 0.5) / 3.0 - 0.5);
    float3 c = float3(cos(a), sin(a), v * 3.4);
    float body = snoise(float3(c.xy * 1.1, c.z * 0.35) + 11.0);
    // slip smeared round by the hands: long along the turn, thin up the wall
    float sa = a + 0.35 * v;
    float smear = smoothstep(-0.1, 0.8, snoise(float3(cos(sa) * 1.3, sin(sa) * 1.3, v * 7.5) + 3.0));
    float dg = drag(vs, a);
    // two thumb wipes: thinner, paler slip, long round the turn
    float tw = exp(-sq(wrapPi(a - 0.6) / 0.42) - sq((v - 0.30) / 0.045))
             + 0.8 * exp(-sq(wrapPi(a + 2.3) / 0.30) - sq((v - 0.62) / 0.035));
    tw *= pull() * (0.8 + 0.2 * snoise(float3(c.xy * 6.0, v * 30.0)));
    // iron spots: sparse, larger than the grog
    float2 cell = float2((a + 3.14159265) * 7.0, v * 15.0);
    float2 ci = floor(cell), cf = frac(cell);
    ci.x = fmod(ci.x + 44.0, 44.0);
    float hsp = hash21(ci + 0.37);
    float2 at = float2(hash21(ci + 7.1), hash21(ci + 3.3)) * 0.7 + 0.15;
    float rad = 0.07 + 0.08 * hash21(ci + 9.9);
    float iron = step(0.90, hsp) * (1.0 - smoothstep(rad * 0.6, rad, length((cf - at) * float2(1.0, 1.6))));
    float dk = smoothstep(0.70, 0.78, snoise(c * 22.0));
    float gr = smoothstep(0.74, 0.82, snoise(c * 26.0 + float3(7.3, 1.1, 3.7)));
    float3 cc = base * (0.93 + 0.10 * body);
    cc = lerp(cc, slipC, saturate(smear * 0.28 + dg * 0.55 + tw * 0.6));
    cc = lerp(cc, darkC, saturate(dk * 0.85 + iron * 0.9));
    cc = lerp(cc, grogC, gr * 0.7);
    alb += cc;
    streakA += smear; dragA += dg; wipeA += saturate(tw);
    speck += saturate(dk + gr);
  }
  alb /= 3.0; streakA /= 3.0; speck /= 3.0; dragA /= 3.0; wipeA /= 3.0;
  float groove = smoothstep(0.1, 0.9, -sin(6.2831853 * v * 13.0 - th)) * pull();
  float wet = 0.58 + 0.42 * exp(-sq((v - kTouch()) / 0.2)) + 0.22 * smoothstep(0.82, 1.0, v)
            + 0.14 * streakA + 0.40 * (1.0 - smoothstep(0.0, 0.08, v)) + 0.10 * groove
            + 0.45 * dragA - 0.45 * wipeA;
  wet = saturate(wet + inside * 0.3);
  alb *= lerp(1.0, 0.70, wet) * lerp(1.0, 0.85, inside);
  m.alb = alb;
  m.metal = 0.0;
  m.rough = 0.62;
  m.coat = wet * (1.0 - 0.5 * speck);
  m.coatRough = max(lerp(0.30, 0.07, wet), 0.13 * smoothstep(0.955, 0.99, v));
  return m;
}

// Slip splats flung on the head: polar centre, radial and tangential half sizes.
static const float4 SPLATS[7] = {
  float4(0.40, 1.10, 0.030, 0.070), float4(1.75, 1.34, 0.022, 0.100), float4(2.65, 1.00, 0.026, 0.045),
  float4(3.70, 1.48, 0.030, 0.140), float4(4.45, 1.20, 0.018, 0.040), float4(5.30, 1.42, 0.026, 0.080),
  float4(5.95, 1.04, 0.020, 0.035) };

Mat wheelMat(float3 p) {
  Mat m;
  float3 q = rotY(p, -g_spin);
  float r = length(q.xz);
  float th = atan2(q.z, q.x);
  float Rf = bodyR(0.0) + 0.05 * kWob();
  float3 alu = lin(float3(0.80, 0.80, 0.80));
  float3 slurry = lin(float3(0.50, 0.27, 0.18));
  float3 filmC = lin(float3(0.66, 0.53, 0.46));
  float3 dried = lin(float3(0.82, 0.64, 0.51));
  float clay = 0.0, wet = 0.0, dry = 0.0, scratch = 0.0;
  for (int k = 0; k < 3; k++) {
    float a = th + g_dspin * ((float(k) + 0.5) / 3.0 - 0.5);
    float2 xz = float2(cos(a), sin(a)) * r;
    // slurry round the foot, its edge uneven
    float edge = Rf + 0.15 + 0.05 * snoise(float3(cos(a) * 1.6, sin(a) * 1.6, 1.7)) + 0.02 * snoise(float3(xz * 7.0, 4.0));
    float ring = 1.0 - smoothstep(edge - 0.03, edge + 0.012, r);
    // arcs the sponge left: thin, broken, part of a turn each
    float film = 0.55 + 0.25 * snoise(float3(cos(a) * 1.2, sin(a) * 1.2, r * 2.5) + 5.0);
    film *= 1.0 - 0.6 * exp(-sq(wrapPi(a - 2.2) / 0.45)) * exp(-sq((r - 1.38) / 0.16));
    float arcs = max(film * (0.8 + 0.2 * sin(r * 41.0 + 1.5 * snoise(float3(xz * 1.4, 2.0)))), 0.0) * 0.8;
    // splats, some still wet, the rest dried paler
    float sp = 0.0, spd = 0.0;
    for (int i = 0; i < 7; i++) {
      float4 s = SPLATS[i];
      float dt = wrapPi(a - s.x) * r;
      float dr = r - s.y;
      float wob = 0.25 * snoise(float3(dt * 18.0, dr * 18.0, float(i) * 3.1));
      float e = length(float2(dt / s.w, dr / s.z)) + wob;
      float c = 1.0 - smoothstep(0.85, 1.0, e);
      sp = max(sp, c);
      spd = max(spd, c * step(0.5, frac(float(i) * 0.37 + 0.2)));
    }
    // a tool scratch, bright through the satin
    float2 s0 = float2(0.62, 1.02), s1 = float2(1.38, 0.42);
    float2 pa = xz - s0, ba = s1 - s0;
    float hh = saturate(dot(pa, ba) / dot(ba, ba));
    float sd = length(pa - ba * hh);
    float scr = (1.0 - smoothstep(0.003, 0.009, sd)) * smoothstep(0.0, 0.12, hh) * smoothstep(1.0, 0.8, hh);
    clay += saturate(max(max(ring, arcs), sp));
    wet += saturate(ring + (sp - spd));
    dry += spd;
    scratch += scr;
  }
  clay /= 3.0; wet /= 3.0; dry /= 3.0; scratch /= 3.0;
  float lathe = 0.5 + 0.5 * sin(r * 180.0);
  float3 cc = lerp(filmC, slurry, saturate(wet));
  cc = lerp(cc, dried, saturate(dry / max(clay, 1e-3)));
  m.alb = lerp(alu * (0.96 + 0.04 * lathe) * (1.0 + 0.2 * scratch), cc, clay);
  m.metal = 1.0 - clay;
  m.rough = lerp(0.24 + 0.05 * lathe - 0.1 * scratch, lerp(0.75, 0.5, wet), clay);
  m.coat = saturate(wet) * clay;
  m.coatRough = 0.12;
  return m;
}

Mat panMat(float3 p) {
  Mat m;
  float spots = smoothstep(0.6, 0.8, snoise(p * 3.0 + 2.0)) * 0.5 + smoothstep(0.78, 0.86, snoise(p * 9.0)) * 0.6;
  m.alb = lerp(lin(float3(0.085, 0.080, 0.076)), lin(float3(0.50, 0.37, 0.29)), saturate(spots) * 0.5);
  m.metal = 0.0; m.rough = 0.55; m.coat = 0.0; m.coatRough = 0.5;
  return m;
}

// ---- shading -------------------------------------------------------------
float3 shadeHit(float3 p, float3 rd, float t, float id) {
  float3 n = calcNormal(p, t);
  float3 v = -rd;
  Mat m;
  float3 nc = n;
  if (id < 1.5) {
    m = clayMat(p);
    // the water film fills the grooves: its surface is smoother than the clay
    g_ring = 0.6;
    nc = calcNormal(p, t);
    g_ring = 1.0;
    // the slip film is uneven: its reflection wavers, and turns with the pot
    float3 qo = rotY(p, -g_spin) * float3(2.6, 8.0, 2.6);
    float3 pert = float3(snoise(qo), snoise(qo + 17.1), snoise(qo + 31.7));
    nc = normalize(nc + 0.055 * pert);
  } else if (id < 2.5) m = wheelMat(p);
  else m = panMat(p);
  float3 Lv = lightC() - p;
  float dl = length(Lv);
  float3 L = Lv / dl;
  // a black flag below the window keeps its light off the wheel's near edge
  float flag = smoothstep(1.8, 1.05, p.z - 0.2 * p.x);
  float ff = windowFF(p, n) * flag;
  // rings and drag marks are relief: their shading is in the normal, so
  // shadows and occlusion are traced without them (no ridge self-shadowing)
  g_ring = 0.0;
  float sh = ff > 0.0 ? softShadow(p + n * 0.01, L, dl, 5.0) : 0.0;
  float ao = calcAO(p, n);
  g_ring = 1.0;
  float nv = saturate(dot(n, v));
  float3 r = reflect(rd, n);
  float3 F0 = lerp(float3(0.04, 0.04, 0.04), m.alb, m.metal);
  float3 F = F0 + (1.0 - F0) * pow(1.0 - nv, 5.0);
  float3 amb = env(n) * 1.6 + env(float3(0.0, -1.0, 0.0)) * 0.4 * saturate(-n.y);
  float occ = ao * ao;
  if (id > 1.5 && id < 2.5) {
    float s = length(p.xz) - (bodyR(0.0) + 0.02);
    occ *= 1.0 - 0.6 * exp(-max(s, 0.0) / 0.16);
  }
  float3 diff = m.alb * (1.0 - m.metal) * (LRAD * ff * sh + amb * occ);
  float3 envR = lerp(env(r), env(normalize(r + n)), saturate(m.rough * 1.3));
  float3 spec = F * (LRAD * windowSpec(p, r, m.rough) * sh * flag + envR * occ);
  // the wet film: a sheen with a sharp core and a soft halo
  float3 rc = reflect(rd, nc);
  float Fc = 0.02 + 0.98 * pow(1.0 - saturate(dot(nc, v)), 5.0);
  float ws = 0.6 * windowSpec(p, rc, m.coatRough) + 0.4 * windowSpec(p, rc, min(m.coatRough * 2.3 + 0.08, 0.9));
  float3 envC = lerp(env(rc), env(normalize(rc + nc)), saturate(m.coatRough * 1.3));
  float3 coat = m.coat * Fc * 1.8 * (LRAD * ws * sh * flag + envC * occ);
  return (diff + spec) * (1.0 - m.coat * Fc) + coat;
}

float3 tonemap(float3 x) {
  return saturate((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14));
}

float4 shade(float2 pos, float px) {
  float2 sz = size();
  float tm = time();
  float az = radians(param(9)), el = radians(param(10));
  float dist = param(11);
  float3 target = float3(0.0, param(12), 0.0);
  float3 eye = target + dist * float3(sin(az) * cos(el), sin(el), cos(az) * cos(el));
  float3 fw = normalize(target - eye);
  float3 rt = normalize(cross(fw, float3(0.0, 1.0, 0.0)));
  float3 up = cross(rt, fw);
  float focal = 1.0 / tan(radians(FOV) * 0.5);
  float shift = param(14) * 2.0;
  float aper = param(15);
  float frame = floor(tm * 30.0 + 0.5);
  float rnd = hash21(pos + float2(frame * 7.13, frame * 3.71));
  float3 acc = float3(0.0, 0.0, 0.0);
  float cover = 0.0;
  for (int s = 0; s < NS; s++) {
    float fs = (float(s) + rnd) / float(NS);
    float ja = 6.2831853 * (float(s) / float(NS) + rnd * 0.37) + 0.6;
    float2 jit = float2(cos(ja), sin(ja)) * 0.36;
    g_spin = spinAt(tm + (fs - 0.5) * SHUTTER);
    g_dspin = spinRate(tm) * SHUTTER / float(NS);
    g_rnd = frac(rnd * 1.7 + float(s) * 0.618034);
    float2 q = (pos + jit - sz * 0.5) / (sz.y * 0.5);
    q.y -= shift;
    float3 rd = normalize(fw * focal + rt * q.x - up * q.y);
    float la = 6.2831853 * frac(float(s) * 0.618034 + rnd * 0.71);
    float lr = aper * sqrt(frac(fs * 0.7 + 0.15));
    float3 ro = eye + (rt * cos(la) + up * sin(la)) * lr;
    float3 fp = eye + rd * (dist / dot(rd, fw));
    rd = normalize(fp - ro);
    float2 hit = march(ro, rd);
    if (hit.x > 0.0) {
      float3 p = ro + rd * hit.x;
      acc += tonemap(shadeHit(p, rd, hit.x, hit.y) * EXPOSURE);
      cover += 1.0;
    }
  }
  return float4(acc / float(NS), cover / float(NS));
}

// Where the window's light crosses the air: it comes in from the left at
// about the pot's height and spreads and fades across the frame.
//   u0 haze strength   u1 mode (0: the haze it lights, premultiplied, to add;
//                                 1: the light's matte, to mask the dust)
float4 shade(float2 pos, float px) {
  float2 sz = size();
  float x = pos.x / sz.x;
  float yc = 0.53 * sz.y - 0.10 * pos.x;
  float spread = 0.16 * sz.y + 0.22 * pos.x;
  float band = exp(-pow((pos.y - yc) / spread, 2.0));
  float m = band * (1.0 - smoothstep(0.05, 1.05, x));
  if (param(1) > 0.5) return float4(m, m, m, m);
  float3 haze = float3(1.0, 0.86, 0.70) * param(0) * m;
  return float4(haze, max(haze.r, max(haze.g, haze.b)));
}

